#!/usr/bin/env bash
# A LINKER SCRIPT NAMED INSIDE -Wl AND WRITTEN BY ANOTHER EDGE.
#
# compiler-rt's nsan library links with
# `-Wl,--version-script,<build>/lib/nsan/clang_rt.nsan-dynamic-x86_64.vers`,
# and the .vers is generated by a different edge in the same build. The link
# does not declare it, so nothing carries it and ld.bfd exits
# `cannot open linker script file ...: No such file or directory`.
#
# The -Wl reader already handles --version-script (libssh, json-c, p11-kit).
# Both of those name a file that EXISTS ON DISK when the driver resolves.
# This fixture asks the other half of the question: the same flag naming a
# file that is a GRAPH NODE another edge produces. Two guards in that loop
# can drop it, and this gate says which:
#   `!p.is_file()`                     the file is not written yet
#   `files.lookup(..).input.is_some()` it IS a produced node, skipped on the
#                                      theory that it reaches the task
#                                      through its own edge, which is only
#                                      true when this edge declares it
#
# Configuration A, seconds. Blanket OFF. Needs gcc.
#   PASS    the shared library links
#   FAIL    otherwise, and the verdict names which guard is responsible
set -u
F='nix-command flakes dynamic-derivations ca-derivations recursive-nix'
REPO=$(cd "$(dirname "$0")" && while [ ! -f Cargo.toml ] && [ "$PWD" != / ]; do cd ..; done; pwd)
CORES=${NN_GATE_CORES:-8}
b() { nice -n 10 nix build --cores "$CORES" --extra-experimental-features "$F" \
        --no-link --print-out-paths "$@"; }
px() { b --impure --expr "let f = builtins.getFlake \"$REPO\"; p = f.inputs.nixpkgs.legacyPackages.\${builtins.currentSystem}; in p.$1" | tail -1; }

CONTROL_REV=""
[ "${1:-}" = "--control" ] && CONTROL_REV=${2:?--control needs a revision}
SRC=${NN_GATE_SRC:-$REPO}
if [ -n "$CONTROL_REV" ]; then
  W=$(mktemp -d -t nn-vers-wt-XXXXXX)
  git -C "$REPO" worktree add -q --detach "$W" "$CONTROL_REV" || exit 1
  GIT=$(command -v git)
  trap '"$GIT" -C "$REPO" worktree remove --force "$W" >/dev/null 2>&1 || true' EXIT
  SRC=$W; echo "control: driver and task binary built from $CONTROL_REV"
fi

NN=$(b "$SRC#nix-ninja") || { echo "NO ANSWER: the nix-ninja binary did not build for NN"; exit 2; }
TASK=$(b "$SRC#nix-ninja-task") || { echo "NO ANSWER: the nix-ninja-task binary did not build for TASK"; exit 2; }
CU=$(px coreutils); BASH=$(px bash); PE=$(px patchelf); CC=$(px gcc); GR=$(px gnugrep)
NIXP=$(b --impure --expr "(builtins.getFlake \"$REPO\").inputs.nix.packages.\${builtins.currentSystem}.default" | tail -1)

D=$(mktemp -d -t nn-vers-XXXXXX); S=$D/src; mkdir -p "$S" "$D/build/lib/nsan"
# ONE EXIT TRAP CARRIES BOTH CLEANUPS: bash keeps only the last one armed, so a
# second trap here once dropped the control worktree removal armed above. Each
# action ends `|| true` because errexit applies inside the trap, and git is the
# path resolved above because PATH no longer holds it when the trap runs.
trap '[ "${KEEP:-}" = 1 ] || rm -rf "$D" || true; [ -z "${W:-}" ] || "$GIT" -C "$REPO" worktree remove --force "$W" >/dev/null 2>&1 || true' EXIT
printf 'int nsan_init(void){return 0;}\n' > "$S/nsan.c"
# The generator writes the version script. Its content must be a real
# version script or ld rejects it for a different reason than the one
# under test.
printf '#!/bin/sh\nprintf "{ global: nsan_init; local: *; };\\n" > "$1"\n' > "$S/genvers.sh"
chmod +x "$S/genvers.sh"
cat > "$D/build/build.ninja" <<NINJA
rule GEN
  command = \$COMMAND
rule CC
  command = gcc -fPIC -MD -MF \$out.d -c \$in -o \$out
  deps = gcc
  depfile = \$out.d
rule LINK
  command = \$COMMAND

build lib/nsan/clang_rt.nsan-dynamic-x86_64.vers: GEN
  COMMAND = $S/genvers.sh lib/nsan/clang_rt.nsan-dynamic-x86_64.vers
build nsan.o: CC $S/nsan.c
build lib/linux/libclang_rt.nsan-x86_64.so: LINK nsan.o
  COMMAND = gcc -shared -o lib/linux/libclang_rt.nsan-x86_64.so nsan.o -Wl,--version-script,$D/build/lib/nsan/clang_rt.nsan-dynamic-x86_64.vers
NINJA
mkdir -p "$D/build/lib/linux"
cd "$D/build"
export PATH="$NN/bin:$TASK/bin:$NIXP/bin:$CC/bin:$CU/bin:$BASH/bin:$PE/bin:$GR/bin"
export NIX_NINJA_TASK=$TASK/bin/nix-ninja-task NIX_CONFIG="experimental-features = $F"
export NIX_NINJA_IMPLICIT_INPUTS_LIMIT=0
set +e
# The generator first, so the .vers EXISTS on disk when the link resolves.
# That isolates the second guard: if the link still fails with the file
# present, the produced-node skip is responsible, not the existence check.
nix-ninja lib/nsan/clang_rt.nsan-dynamic-x86_64.vers > "$D/gen.log" 2>&1; grc=$?
present=no; [ -f lib/nsan/clang_rt.nsan-dynamic-x86_64.vers ] && present=yes
nix-ninja lib/linux/libclang_rt.nsan-x86_64.so > "$D/link.log" 2>&1; lrc=$?
set -e
echo "generator rc=$grc, version script on disk: $present"

# ARM 2, REPORTED AND SCORING NOTHING WHILE THE CLASS IS OPEN.
#
# Arm 1 runs the generator FIRST so the .vers is on disk when the link
# resolves. Its own comment says that isolates the produced-node skip, which
# means it DELIBERATELY excludes the existence check sitting above that skip.
# This arm removes the pre-build and asks for the link alone.
#
# THE FIRST VERSION OF THIS ARM MODELLED A GRAPH compiler-rt DOES NOT HAVE,
# and it reproduced the package's error text while doing it, which is the
# whole reason the geometry is now written out here rather than trimmed to
# what fails. It had the .vers produced by an edge and NOTHING ordering it
# before the link, so the driver was asked to build a graph real ninja
# cannot build either. compiler-rt orders it, through an object:
#
#   SanitizerUtils.cmake      add_sanitizer_rt_version_list makes the .vers
#                             an add_custom_command OUTPUT
#   lib/nsan/CMakeLists.txt   set_property(SOURCE dummy.cpp APPEND PROPERTY
#                             OBJECT_DEPENDS <...>.vers)
#   the link                  takes dummy.cpp.o as an input
#
# so the real chain is .vers -> dummy.o -> link, ninja orders it
# deterministically, and the ordering is what a sandbox cannot use: the link
# task must DECLARE the .vers as an INPUT, and the link edge's declared
# inputs are the objects. Carrying it is the -Wl reader's job. The fixture
# below is that geometry, and REAL NINJA IS THE CONTROL: a graph real ninja
# cannot build is an undeclared dependency and says nothing about the driver.
#
# THE SPELLING IS ABSOLUTE ON PURPOSE. cmake emits
# ${CMAKE_CURRENT_BINARY_DIR}/<name>.vers, and graph names are ninja
# spellings, so a lookup taken on the candidate as written cannot match.
# CONFIGURATION A RELATIVISES IT, which is why this arm may pass here while
# the consumer's route fails; version-script-generated-b.sh is the instrument
# that reaches that, the same way shim-link-include-b.sh does for -I.
#
# It scores nothing until the class closes, because a red arm in a corpus
# stops a red run meaning do not spend the machine. TRIGGER: move it into the
# verdict in the commit that closes the class, on the strength of a B run.
D2=$(mktemp -d -t nn-vers2-XXXXXX)
# Re-armed to cover D2 as well, so it carries the worktree removal again.
trap '[ "${KEEP:-}" = 1 ] || rm -rf "$D" "$D2" || true; [ -z "${W:-}" ] || "$GIT" -C "$REPO" worktree remove --force "$W" >/dev/null 2>&1 || true' EXIT
S2=$D2/src; mkdir -p "$S2"
cp "$S/nsan.c" "$S/genvers.sh" "$S2/"
printf 'int nsan_dummy(void){return 0;}\n' > "$S2/dummy.c"
V=lib/nsan/clang_rt.nsan-dynamic-x86_64.vers

# THE ABSOLUTE -Wl PATH DOES NOT SURVIVE A DIRECTORY COPY, so the fixture is
# EMITTED per directory rather than copied into one. The first control here
# was a `cp -a` of the driver's tree, which left the link naming the .vers in
# the ORIGINAL directory: real ninja built the script beside itself, the link
# looked somewhere else, and the control reported that real ninja could not
# build the graph. A broken control accusing the fixture reads exactly like a
# fixture accusing the driver, one level further out.
emit_fixture() {
  local dir=$1
  mkdir -p "$dir/lib/nsan" "$dir/lib/linux"
  cat > "$dir/build.ninja" <<NINJA
rule GEN
  command = \$COMMAND
rule CC
  command = gcc -fPIC -MD -MF \$out.d -c \$in -o \$out
  deps = gcc
  depfile = \$out.d
rule LINK
  command = \$COMMAND

build $V: GEN
  COMMAND = $S2/genvers.sh $V
build nsan.o: CC $S2/nsan.c
build dummy.o: CC $S2/dummy.c | $V
build lib/linux/libclang_rt.nsan-x86_64.so: LINK nsan.o dummy.o
  COMMAND = gcc -shared -o lib/linux/libclang_rt.nsan-x86_64.so nsan.o dummy.o -Wl,--version-script,$dir/$V
NINJA
}
emit_fixture "$D2/build"

# THE FIXTURE CONTROL, and it is the one that was missing. If real ninja
# cannot build this graph then the dependency is undeclared and any driver
# failure below is a statement about the fixture.
NJ=$(px ninja 2>/dev/null)
if [ -n "$NJ" ] && [ -x "$NJ/bin/ninja" ]; then
  emit_fixture "$D2/njctl"
  set +e
  ( cd "$D2/njctl" && PATH="$CC/bin:$CU/bin:$BASH/bin" "$NJ/bin/ninja" \
      lib/linux/libclang_rt.nsan-x86_64.so ) > "$D2/njctl.log" 2>&1
  njrc=$?
  set -e
  if [ $njrc -ne 0 ]; then
    echo "arm 2  NO ANSWER  real ninja cannot build this graph either"
    grep -m1 'cannot open linker script' "$D2/njctl.log" || tail -2 "$D2/njctl.log"
    echo "         the fixture declares no route from the .vers to the link;"
    echo "         fix the fixture, not the driver"
    a2skip=1
  else
    echo "arm 2  control OK  real ninja builds this graph, so the driver owes it"
  fi
else
  echo "arm 2  NO ANSWER  no ninja to control the fixture with"
  a2skip=1
fi

if [ "${a2skip:-0}" != 1 ]; then
  set +e
  ( cd "$D2/build" && nix-ninja lib/linux/libclang_rt.nsan-x86_64.so > "$D2/link.log" 2>&1 )
  a2rc=$?
  set -e
  a2present=no; [ -f "$D2/build/$V" ] && a2present=yes
  if [ $a2rc -eq 0 ]; then
    echo "arm 2  BUILT   the link asked for alone carried the script (script on disk after: $a2present)"
  else
    echo "arm 2  FAILED  the link asked for alone (open class, scores nothing)"
    # THE ABORT NAMES A DERIVATION, NOT THE ERROR. The driver reports the
    # resolved derivation it could not build; the linker's own words are in
    # that derivation's log, one level down. Reading only the abort is how a
    # live class and a broken fixture become indistinguishable.
    leaf=$(grep -oE "/nix/store/[a-z0-9]{32}-ninja-build\\.drv" "$D2/link.log" | tail -1)
    if [ -n "$leaf" ]; then
      nix log "$leaf" 2>/dev/null | grep -oE "cannot open linker script file [^:]*" | head -1
    else
      echo "         NO ANSWER: the abort named no derivation to read"
    fi
  fi
fi

if [ -n "$CONTROL_REV" ]; then
  if [ $lrc -ne 0 ]; then
    echo "CONTROL PASS: $CONTROL_REV does not carry the generated version script (rc=$lrc)"
    grep -o 'cannot open linker script file[^"]*' "$D/link.log" | head -1
    exit 0
  fi
  echo "CONTROL FAILED: expected the link to fail at $CONTROL_REV"; exit 1
fi
# ARM 2 SCORES NOW. Its trigger said it joins the verdict in the commit that
# carries a produced node on the strength of the GRAPH rather than on bytes
# being present, and that is this one. It is skipped rather than failed where
# its own ninja control could not run, because an arm that could not be
# controlled is NO ANSWER and not a pass.
if [ "${a2skip:-0}" = 1 ]; then
  echo "NO ANSWER: arm 2 could not be controlled, so this run scores nothing"
  exit 2
fi
if [ $lrc -eq 0 ] && [ -f lib/linux/libclang_rt.nsan-x86_64.so ] && [ "${a2rc:-1}" -eq 0 ]; then
  echo "PASS: a version script written by another edge is carried into the link"
  exit 0
fi
if [ "${a2rc:-1}" -ne 0 ]; then
  echo "FAIL: arm 2, the link asked for alone did not carry the generated script"
  echo "  real ninja builds this graph, so the dependency is declared and the"
  echo "  driver dropped it"
  exit 1
fi
echo "FAIL: link rc=$lrc, version script present=$present"
if [ "$present" = yes ]; then
  echo "  the file was ON DISK and still not carried: the produced-node skip is responsible"
else
  echo "  the file was NOT on disk when the link resolved: the existence check is responsible"
fi
grep -E 'cannot open linker script|ABORTED' "$D/link.log" | head -3
exit 1
